import {FunctionalComponent } from 'preact';
import CloseIcon from '@material-ui/icons/Cancel';

import styles from './styles.module.scss';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const Close: any = CloseIcon;

interface Props {
  onClose: () => void;
  children: React.ReactNode;
  className?: string;
}

const ModalTemplate: FunctionalComponent<Props> = ({
  className = '',
  onClose,
  children,
}: Props) => {
  return (
    <div className={`${styles.modal} ${styles[className]}`} onClick={onClose}>
      <div
        className={styles.modalContent}
        onClick={(e): void => e.stopPropagation()}
      >
        <div className={styles.modalContentWrapper}>
          <div className={styles.closeButton} onClick={onClose}>
            <Close fontSize="small" className={styles.closeIcon} />
          </div>
          <div className={styles.modalChildren}>{children}</div>
        </div>
      </div>
    </div>
  );
};

export default ModalTemplate;
