import { FunctionalComponent} from 'preact';
import { useDispatch } from 'react-redux';

import { clickedSupportUs } from '../../slice';
import styles from './styles.module.scss';

import ArrowForwardIcon from '@material-ui/icons/ArrowForward';
import Modal from '../../../../shared/Modal/ModalTemplate';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const ArrowForward: any = ArrowForwardIcon;

const Patreon: FunctionalComponent = () => {
  const dispatch = useDispatch();

  const closeModal = (): void => {
    dispatch(clickedSupportUs(null));
  };

  const redirectToPatreon = (): void => {
    closeModal();
  };

  return (
    <Modal onClose={closeModal}>
      <div className={styles.patreon}>
        <p className={styles.patreonHeader}>
          Wow! Great that you are considering supporting us even more than you
          already do!
        </p>
        <p className={styles.patreonBody}>
          If you want to support us with a direct contribution, you can do so on{' '}
          <b>our Patreon</b> site.
        </p>
        <p className={styles.patreonBodyPart}>
          Patreon is a website that enables initiatives like ours to collect
          funds from their supporters.
        </p>
        <a
          onClick={redirectToPatreon}
          href={'https://www.patreon.com/oceanhero'}
          className={styles.openPatreonBtn}
        >
          Open Patreon
        </a>
        <a
          href="https://docs.google.com/forms/d/e/1FAIpQLSeSRa_OR9-b0c1znEneR34FBg295jPgpU1VNgXHzAZKYIJDQw/viewform?usp=sf_link"
          className={styles.survey}
          target="_blank"
          rel="noreferrer"
        >
          <ArrowForward className={styles.arrow} />
          <div className={styles.feedback}>
            Tell us what we need to improve, so that you would support us with a
            direct contribution
          </div>
        </a>
      </div>
    </Modal>
  );
};

export default Patreon;
